using System;
using UnityEngine;

namespace Astrea;

[CreateAssetMenu(fileName = "PlayXVirtuesOmenData", menuName = "Data/Battle/Omens System/Omen Data/Any/PlayXVirtuesOmenData")]
public class PlayXVirtuesOmenData : OmenData
{
	[Header("PlayXVirtuesOmenData")]
	[SerializeField]
	private bool playXVirtuesInASingleTurn;

	[SerializeField]
	private bool corruptionNotIncreasedByCorruptionModifier;

	[Header("Run Modifier")]
	[SerializeField]
	private bool usedAsRunModifierOmenData;

	[NonSerialized]
	private OmenInstance omenInstance;

	[NonSerialized]
	private Action omenAction;

	public override void Initialize(OmenInstance omenInstance)
	{
		this.omenInstance = omenInstance;
		if (playXVirtuesInASingleTurn)
		{
			ReferenceSingleton<StartBattleStartEndTurnOmensHandler>.Instance.RestartStartTurnOmens.Add(omenInstance);
			ReferenceSingleton<StartBattleStartEndTurnOmensHandler>.Instance.RestartEndBattleOmens.Add(omenInstance);
		}
		omenAction = OmenAction(omenInstance);
		ReferenceSingleton<MiscOmensHandler>.Instance.OnPlayerPlayVirtueOmenAction.Add(omenAction);
	}

	public Action OmenAction(OmenInstance omenInstance)
	{
		return delegate
		{
			if (!AlreadyUsed)
			{
				ActivateOmen();
				if (counter == 0)
				{
					if (playXVirtuesInASingleTurn)
					{
						ToggleAlreadyUsed(toggle: true);
						if (!usedAsRunModifierOmenData)
						{
							omenInstance.ToggleOmenCounter(toggle: false);
							omenInstance.DisableOmen();
						}
					}
					if (!usedAsRunModifierOmenData)
					{
						omenInstance.EnqueueOmenFeedbackAndPlay();
						omenInstance.StopBlinkingFeedback();
					}
				}
				if (!AlreadyUsed && !usedAsRunModifierOmenData)
				{
					omenInstance.UpdateOmenCounter();
					if (counter == TriggerAmount - 1)
					{
						omenInstance.PlayBlinkingFeedback();
					}
				}
			}
		};
	}

	protected override void OmenLogicActiveOmen(int actionAmount, GameObject target = null, CorruptionPurifyModifierEnum corruptionPurifyModifierEnum = CorruptionPurifyModifierEnum.NONE)
	{
		if (corruptionNotIncreasedByCorruptionModifier)
		{
			base.OmenLogicActiveOmen(actionAmount, target, CorruptionPurifyModifierEnum.CANTBEINCREASEDCORRUPTION);
		}
		else
		{
			base.OmenLogicActiveOmen(actionAmount, target);
		}
	}

	public override void OmenRemoved()
	{
		base.OmenRemoved();
		if (playXVirtuesInASingleTurn)
		{
			ReferenceSingleton<StartBattleStartEndTurnOmensHandler>.Instance.RestartStartTurnOmens.Remove(omenInstance);
			ReferenceSingleton<StartBattleStartEndTurnOmensHandler>.Instance.RestartEndBattleOmens.Remove(omenInstance);
		}
		ReferenceSingleton<MiscOmensHandler>.Instance.OnPlayerPlayVirtueOmenAction.Remove(omenAction);
	}

	protected override string GetOmenRawLocalizedDescription()
	{
		if (playXVirtuesInASingleTurn)
		{
			return ReferenceSingleton<LocalizationManager>.Instance.GetLocalizedString("PlayXVirtuesInASingleTurn");
		}
		if (EnableOmenCounter)
		{
			return ReferenceSingleton<LocalizationManager>.Instance.GetLocalizedString("EveryXTimesPlayVirtue");
		}
		return ReferenceSingleton<LocalizationManager>.Instance.GetLocalizedWheneverPlayAVirtue().Replace(" {0}", "").Replace("{0}", "");
	}

	public override string OmenConvertedDescription()
	{
		string text = "";
		if (corruptionNotIncreasedByCorruptionModifier)
		{
			text = "\n" + base.localizationManager.GetLocalizedCorruptionNotIncreasedByCorruptionModifier();
		}
		return base.OmenConvertedDescription() + text;
	}
}
